#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import json, re, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

PROJECTS_BASE = r"C:\Users\tensh\.claude\projects\C--Users-tensh-eigo-radio"

SESSIONS = [
    "294958fe-da6e-491c-8a02-4f864d8195c8",
    "a146ec25-1821-49c1-a6f2-3b7ad423406a",
    "eba13a8b-6eec-4381-909a-3a2d71be7123",
]

USAGE_RE = re.compile(
    r'<subagent_tokens>(\d+)</subagent_tokens>\s*<tool_uses>(\d+)</tool_uses>\s*<duration_ms>(\d+)</duration_ms>'
)
TASKID_RE = re.compile(r'<task-id>([0-9a-fA-F]+)</task-id>')
TOOLUSEID_RE = re.compile(r'<tool-use-id>([^<]+)</tool-use-id>')
SUMMARY_RE = re.compile(r'<summary>(.*?)</summary>', re.DOTALL)
STATUS_RE = re.compile(r'<status>([^<]+)</status>')
MGMT_ID_RE = re.compile(r'管理ID[:：]\s*`?([A-Za-z0-9][A-Za-z0-9\-]{5,120})')

def extract_mgmt_id(text):
    if not text:
        return None
    m = MGMT_ID_RE.search(text)
    return m.group(1).strip() if m else None

def first_text_from_content(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict) and c.get('type') == 'text':
                parts.append(c.get('text',''))
        return '\n'.join(parts)
    return ''

all_notifications = []  # dict per notification
agent_tool_use_by_id = {}  # tool_use_id -> {description, prompt, subagent_type, session}

for session_id in SESSIONS:
    path = f"{PROJECTS_BASE}\{session_id}.jsonl"
    try:
        f = open(path, encoding='utf-8', errors='replace')
    except FileNotFoundError:
        continue
    for lineno, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(d, dict):
            continue
        dtype = d.get('type')

        # capture Agent/Task tool_use calls (Fable delegating)
        if dtype == 'assistant':
            msg = d.get('message', {})
            content = msg.get('content')
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type') == 'tool_use' and c.get('name') in ('Agent','Task'):
                        tuid = c.get('id')
                        inp = c.get('input', {}) or {}
                        prompt = inp.get('prompt','') or ''
                        desc = inp.get('description','') or ''
                        agent_tool_use_by_id[tuid] = {
                            'description': desc,
                            'prompt': prompt,
                            'subagent_type': inp.get('subagent_type'),
                            'session': session_id,
                            'mgmt_id_from_prompt': extract_mgmt_id(prompt) or extract_mgmt_id(desc),
                        }

        if dtype == 'queue-operation':
            content = d.get('content')
            if isinstance(content, str) and 'task-notification' in content and '<usage>' in content:
                um = USAGE_RE.search(content)
                if not um:
                    continue
                subagent_tokens, tool_uses, duration_ms = int(um.group(1)), int(um.group(2)), int(um.group(3))
                tidm = TASKID_RE.search(content)
                tuidm = TOOLUSEID_RE.search(content)
                summ = SUMMARY_RE.search(content)
                statm = STATUS_RE.search(content)
                all_notifications.append({
                    'session': session_id,
                    'timestamp': d.get('timestamp'),
                    'task_id': tidm.group(1) if tidm else None,
                    'tool_use_id': tuidm.group(1) if tuidm else None,
                    'summary': summ.group(1).strip() if summ else None,
                    'status': statm.group(1) if statm else None,
                    'subagent_tokens': subagent_tokens,
                    'tool_uses': tool_uses,
                    'duration_ms': duration_ms,

