        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'text':
                    total += len(c.get('text', '') or '')
                elif 'text' in c:
                    total += len(c.get('text', '') or '')
        return total
    return 0


MGMT_ID_RE = re.compile(r'管理ID[:：]\s*`?([A-Za-z0-9][A-Za-z0-9\-]{5,120})')


