#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Tag each sonnet-worker task record with whether its delegation prompt
contained an explicit E-1/D-1/G-1 reminder (literal tag or paraphrase),
then compare metrics for after-boundary tasks split by reminder presence."""
import json, glob, os, sys, statistics
from datetime import datetime

sys.path.insert(0, r"C:\Users\tensh\eigo-radio")
PROJECTS_BASE = r"C:\Users\tensh\.claude\projects\C--Users-tensh-eigo-radio"
SP = r"C:\Users\tensh\AppData\Local\Temp\claude\C--Users-tensh-eigo-radio\294958fe-da6e-491c-8a02-4f864d8195c8\scratchpad"
BOUNDARY_UTC = datetime.fromisoformat("2026-09-12T11:37:12+00:00")

KEYWORDS = ['E-1', 'D-1', 'G-1', '再読しない', '再読を避け', '全文読込ではなく',
            '該当箇所のみ', '--short', '--quiet', '同一task内で同一ファイル']

# rebuild tool_use_id -> prompt map
main_files = glob.glob(os.path.join(PROJECTS_BASE, "*.jsonl"))
prompt_by_tuid = {}
for mf in main_files:
    with open(mf, encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            if not isinstance(d, dict) or d.get('type') != 'assistant':
                continue
            msg = d.get('message', {})
            content = msg.get('content')
            if not isinstance(content, list):
                continue
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'tool_use' and c.get('name') in ('Agent', 'Task'):
                    inp = c.get('input', {}) or {}
                    prompt_by_tuid[c.get('id')] = inp.get('prompt', '') or ''

recs = []
with open(os.path.join(SP, 'remeasure_per_task_01.jsonl'), encoding='utf-8') as f:
    for line in f:
        recs.append(json.loads(line))

# need tool_use_id per task: re-derive from meta.json
subagent_dirs = glob.glob(os.path.join(PROJECTS_BASE, "*", "subagents"))
tuid_by_taskid = {}
for sd in subagent_dirs:
    for fn in os.listdir(sd):
        if fn.endswith('.meta.json'):
            task_id = fn[len('agent-'):-len('.meta.json')]
            try:
                with open(os.path.join(sd, fn), encoding='utf-8', errors='replace') as f:
                    meta = json.load(f)
                tuid_by_taskid[task_id] = meta.get('toolUseId')
            except Exception:
                pass

for r in recs:
    tuid = tuid_by_taskid.get(r['task_id'])
    prompt = prompt_by_tuid.get(tuid, '') if tuid else ''
    r['has_reminder'] = any(k in prompt for k in KEYWORDS)

sonnet = [r for r in recs if r['agent_type'] == 'sonnet-worker']
before = [r for r in sonnet if r['period'] == 'before']
after = [r for r in sonnet if r['period'] == 'after']
after_r = [r for r in after if r['has_reminder']]
after_nr = [r for r in after if not r['has_reminder']]
before_r = [r for r in before if r['has_reminder']]

print(f"before: n={len(before)} (with_reminder={len(before_r)})")
print(f"after: n={len(after)} with_reminder={len(after_r)} without_reminder={len(after_nr)}")


def stats(vals):
    vals = [v for v in vals if v is not None]
    if not vals:
        return None
    vals_sorted = sorted(vals)
    n = len(vals_sorted)
    return {
        'n': n, 'mean': statistics.mean(vals_sorted), 'median': statistics.median(vals_sorted),
    }


def show(label, groups):
    print(f"--- {label} ---")
    for name, g in groups:
        s = stats(g)
        if s is None:
            print(f"  {name}: n=0")
        else:
            print(f"  {name}: n={s['n']} mean={s['mean']:.3f} median={s['median']:.3f}")


show('reread_rate', [
    ('before(no reminder, n=357)', [r['reread_rate'] for r in before]),
    ('after+reminder', [r['reread_rate'] for r in after_r]),
    ('after-no_reminder', [r['reread_rate'] for r in after_nr]),
])
show('full_read_rate_by_chars', [
    ('before(no reminder, n=357)', [r['full_read_rate_by_chars'] for r in before]),
    ('after+reminder', [r['full_read_rate_by_chars'] for r in after_r]),
    ('after-no_reminder', [r['full_read_rate_by_chars'] for r in after_nr]),
])
show('cumulative_usage', [
    ('before(no reminder, n=357)', [r['cumulative_usage'] for r in before]),
    ('after+reminder', [r['cumulative_usage'] for r in after_r]),
    ('after-no_reminder', [r['cumulative_usage'] for r in after_nr]),
])
show('tool_call_count', [
    ('before(no reminder, n=357)', [r['tool_call_count'] for r in before]),
    ('after+reminder', [r['tool_call_count'] for r in after_r]),
    ('after-no_reminder', [r['tool_call_count'] for r in after_nr]),
])
show('git_ratio', [
    ('before(no reminder, n=357)', [r['git_ratio'] for r in before]),
    ('after+reminder', [r['git_ratio'] for r in after_r]),
    ('after-no_reminder', [r['git_ratio'] for r in after_nr]),
])

# save tagged records
with open(os.path.join(SP, 'remeasure_per_task_01_tagged.jsonl'), 'w', encoding='utf-8') as f:
    for r in recs:
        f.write(json.dumps(r, ensure_ascii=False) + '\n')

